func decodeJsonWebToken(token string, key string) string {
	// BEGIN SOLUTION

	// Parse JWT token
	parsedToken, err := jwt.Parse(token, func(token *jwt.Token) (interface{}, error) {
		// Ensure the algorithm is HS256
