					return strings.TrimSpace(children[0].ResValue())
				}
				return """"
			}

			// Extract student information
			name = getChildContent(""name"")
			age = getChildContent(""age"")
			citizenship = getChildContent(""citizenship"")

			return name, age, citizenship
		}
	}

	return """", """", """"
}
